(function() {

    // Preserve existing List View settings
    const settings = frappe.listview_settings["Deployments"] || {};
    const original_onload = settings.onload;

    settings.onload = function(listview) {

        // Run existing List View functionality
        if (typeof original_onload === "function") {
            original_onload(listview);
        }

        // Multiple Deploy button
        listview.page.add_inner_button("Multiple Deploy", function() {

            let employee_rows = [];

            const dialog = new frappe.ui.Dialog({
                title: "Multiple Deploy",
                size: "large",

                fields: [{
                        label: "Site",
                        fieldname: "custom_sites",
                        fieldtype: "Link",
                        options: "Project",
                        reqd: 1
                    },
                    {
                        fieldtype: "Section Break"
                    },
                    {
                        fieldtype: "HTML",
                        fieldname: "employee_table"
                    }
                ],

                primary_action_label: "Create Deployments",

                primary_action: async function() {

                    const site = dialog.get_value("custom_sites");

                    if (!site) {
                        frappe.msgprint("Please select a Project.");
                        return;
                    }

                    const employees = employee_rows
                        .map(row => row.control.get_value())
                        .filter(Boolean);

                    if (!employees.length) {
                        frappe.msgprint("Please select at least one Employee.");
                        return;
                    }

                    if (new Set(employees).size !== employees.length) {
                        frappe.msgprint("Duplicate Employees are not allowed.");
                        return;
                    }

                    dialog.get_primary_btn().prop("disabled", true);

                    try {

                        let created_count = 0;

                        for (const employee of employees) {

                            await frappe.db.insert({
                                doctype: "Deployments",
                                custom_sites: site,
                                custom_employee_id: employee
                            });

                            created_count++;
                        }

                        dialog.hide();

                        frappe.show_alert({
                            message: `${created_count} Deployment records created successfully.`,
                            indicator: "green"
                        });

                        listview.refresh();

                    } catch (error) {

                        console.error(error);

                        frappe.msgprint({
                            title: "Creation Failed",
                            message: "Unable to create all Deployment records. Please check the mandatory fields and permissions."
                        });

                    } finally {
                        dialog.get_primary_btn().prop("disabled", false);
                    }
                }
            });

            const wrapper = dialog.fields_dict.employee_table.$wrapper;

            wrapper.html(`
                <div style="margin-bottom:12px;">
                    <h5>Employee Selection</h5>
                    <p class="text-muted">
                        Add or remove employees using the buttons below.
                    </p>
                </div>

                <div class="employee-rows"></div>

                <button class="btn btn-sm btn-primary add-employee"
                    style="margin-top:10px;">
                    <i class="fa fa-plus"></i> Add Employee
                </button>
            `);

            const rows_container = wrapper.find(".employee-rows").css({
                "display": "flex",
                "flex-direction": "column",
                "gap": "4px"
            });

            wrapper.append(`
                <style>
                    .employee-rows .form-group {
                        margin-bottom: 0 !important;
                    }
                </style>
            `);

            // Exclude employees already selected in other rows
            function refresh_employee_queries() {

                employee_rows.forEach(row => {

                    row.control.df.get_query = function() {

                        const selected = employee_rows
                            .filter(other => other !== row)
                            .map(other => other.control.get_value())
                            .filter(Boolean);

                        return {
                            filters: [
                                ["Employee", "name", "not in", selected]
                            ]
                        };
                    };

                });
            }

            // Add employee row
            function add_employee_row() {

                const row_wrapper = $(`
                    <div style="
                        display:flex;
                        gap:10px;
                        align-items:center;
                        margin-bottom:4px;
                    ">
                        <div class="employee-input" style="flex:1;"></div>

                        <button class="btn btn-danger btn-sm remove-employee">
                            <i class="fa fa-minus"></i>
                        </button>
                    </div>
                `);

                rows_container.append(row_wrapper);

                const control = frappe.ui.form.make_control({
                    parent: row_wrapper.find(".employee-input"),

                    df: {
                        fieldtype: "Link",
                        options: "Employee",
                        fieldname: "employee",
                        placeholder: "Select Employee",

                        get_query: function() {
                            return {};
                        },

                        onchange: function() {
                            refresh_employee_queries();
                        }
                    },

                    render_input: true
                });

                const row = {
                    wrapper: row_wrapper,
                    control: control
                };

                employee_rows.push(row);

                // Remove employee row
                row_wrapper.find(".remove-employee").on("click", function() {

                    employee_rows = employee_rows.filter(
                        item => item !== row
                    );

                    row_wrapper.remove();

                    refresh_employee_queries();
                });

                refresh_employee_queries();
            }

            // Add employee button
            wrapper.find(".add-employee").on("click", function() {
                add_employee_row();
            });

            // Initial employee row
            add_employee_row();

            dialog.show();

        });

    };

    frappe.listview_settings["Deployments"] = settings;

})();

