async function calculate_basic_pay(frm) {

    console.clear();

    console.log("========== SALARY CALCULATION STARTED ==========");

    try {

        console.log("Employee:", frm.doc.employee);
        console.log("Start Date:", frm.doc.start_date);
        console.log("End Date:", frm.doc.end_date);

        if (!frm.doc.employee || !frm.doc.start_date || !frm.doc.end_date) {
            frappe.msgprint("Please select Employee, Start Date and End Date.");
            return;
        }

        // STEP 1: Fetch Site TimeSheet records

        console.log("STEP 1: Fetching Site TimeSheet records...");

        let response = await frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Site TimeSheet",
                filters: {
                    custom_emp_name: frm.doc.employee,
                    custom_date: [
                        "between",
                        [frm.doc.start_date, frm.doc.end_date]
                    ]
                },
                fields: [
                    "name",
                    "custom_emp_name",
                    "custom_date",
                    "custom_total_hrs",
                    "custom_grade"
                ],
                limit_page_length: 5000
            }
        });

        let records = response.message || [];

        console.log("Site TimeSheet Records Found:", records.length);
        console.table(records);

        // STEP 2: Calculate Basic Pay

        let total_basic = 0;

        for (let row of records) {

            console.group("Processing TimeSheet:", row.name);

            let hours = flt(row.custom_total_hrs);
            let grade_name = row.custom_grade;

            console.log("Date:", row.custom_date);
            console.log("Working Hours:", hours);
            console.log("Grade:", grade_name);

            if (!grade_name) {
                console.warn("Grade is missing. Skipping record.");
                console.groupEnd();
                continue;
            }

            // STEP 3: Fetch Grade hourly rate

            let grade_response = await frappe.db.get_value(
                "Employee Grade",
                grade_name,
                "default_base_pay"
            );

            let hourly_rate = flt(
                grade_response.message &&
                grade_response.message.default_base_pay
            );

            console.log("Grade Hourly Rate:", hourly_rate);

            // STEP 4: Calculate individual Basic Pay

            let record_basic = hours * hourly_rate;

            console.log("Calculation:", hours, "x", hourly_rate);
            console.log("Record Basic Pay:", record_basic);

            total_basic += record_basic;

            console.groupEnd();
        }

        console.log("TOTAL BASIC PAY:", total_basic);

        // STEP 5: Find Basic component in Earnings

        let basic_row = (frm.doc.earnings || []).find(
            d => d.salary_component === "Basic"
        );

        if (!basic_row) {

            frappe.msgprint({
                title: "Basic Component Not Found",
                message: "Please check whether Basic exists in the Earnings table.",
                indicator: "red"
            });

            return;
        }

        // STEP 6: Update Basic amount

        await frappe.model.set_value(
            basic_row.doctype,
            basic_row.name,
            "amount",
            total_basic
        );

        frm.refresh_field("earnings");
        frm.dirty();

        console.log("Basic Pay Updated:", total_basic);

        // STEP 7: Fetch Oman Labour Rules multipliers


        // STEP 7: Fetch Oman Labour Rules multipliers (Single DocType)

        console.log("STEP 7: Fetching Oman Labour Rules...");

        let rules_response = await frappe.call({
            method: "frappe.client.get",
            args: {
                doctype: "Oman Labour Rules",
                name: "Oman Labour Rules"
            }
        });

        let rules = rules_response.message || {};

        let ot_day_multiplier = flt(rules.custom_overtime_day);
        let ot_night_multiplier = flt(rules.custom_overtime_night);
        let rest_multiplier = flt(rules.custom_rest_day__holiday_premium);

        console.log("OT Day Multiplier:", ot_day_multiplier);
        console.log("OT Night Multiplier:", ot_night_multiplier);
        console.log("Rest Day Multiplier:", rest_multiplier);

        // STEP 8: Calculate Basic Hourly Rate

        let basic_hourly_rate = total_basic / 30 / 8;

        console.log("Basic Hourly Rate:", basic_hourly_rate);

        // STEP 9: Calculate Overtime and Rest Day Pay

        let ot_day_hours = flt(frm.doc.custom_ot_day_hours);
        let ot_night_hours = flt(frm.doc.custom_ot_night_hours);
        let rest_day_hours = flt(frm.doc.custom_rest_day_hours);

        let ot_day_amount =
            basic_hourly_rate *
            ot_day_multiplier *
            ot_day_hours;

        let ot_night_amount =
            basic_hourly_rate *
            ot_night_multiplier *
            ot_night_hours;

        let rest_day_amount =
            basic_hourly_rate *
            rest_multiplier *
            rest_day_hours;

        console.log("OT Day Hours:", ot_day_hours);
        console.log("OT Day Amount:", ot_day_amount);

        console.log("OT Night Hours:", ot_night_hours);
        console.log("OT Night Amount:", ot_night_amount);

        console.log("Rest Day Hours:", rest_day_hours);
        console.log("Rest Day Amount:", rest_day_amount);

        // STEP 10: Update Earnings Components

        async function update_earning(component, amount) {

            let earning_row = (frm.doc.earnings || []).find(
                d => d.salary_component === component
            );

            if (!earning_row) {
                console.warn("Earning component not found:", component);
                return;
            }

            await frappe.model.set_value(
                earning_row.doctype,
                earning_row.name,
                "amount",
                amount
            );

            console.log(component + " Updated:", amount);
        }

        await update_earning("OT Day", ot_day_amount);

        await update_earning("OT Night", ot_night_amount);

        await update_earning(
            "Rest Day / Holiday Premium",
            rest_day_amount
        );

        // STEP 11: Refresh Earnings

        frm.refresh_field("earnings");
        frm.dirty();

        console.log("========== FINAL SALARY CALCULATION ==========");

        console.table([{
                Component: "Basic",
                Amount: total_basic
            },
            {
                Component: "OT Day",
                Amount: ot_day_amount
            },
            {
                Component: "OT Night",
                Amount: ot_night_amount
            },
            {
                Component: "Rest Day / Holiday Premium",
                Amount: rest_day_amount
            }
        ]);

        frappe.show_alert({
            message: "Basic Pay and Overtime Earnings Updated Successfully",
            indicator: "green"
        });

        console.log("========== SALARY CALCULATION COMPLETED ==========");

    } catch (error) {

        console.error("SALARY CALCULATION ERROR:", error);

        frappe.msgprint({
            title: "Calculation Error",
            message: error.message || "Check browser console for details.",
            indicator: "red"
        });
    }
