frappe.listview_settings["Payroll Entry"] = {

    onload(listview) {

        listview.page.add_inner_button(
            "Export Payroll Excel",
            async function () {

                // Get only the Payroll Entry records currently loaded
                // in this List View.

                let payroll_entry_names = (listview.data || [])
                    .filter(row => row.name)
                    .map(row => row.name);

                payroll_entry_names = [
                    ...new Set(payroll_entry_names)
                ];

                if (!payroll_entry_names.length) {

                    frappe.msgprint(
                        "No Payroll Entry records are available in the current list."
                    );

                    return;
                }

                let button = listview.page.wrapper.find(
                    'button:contains("Export Payroll Excel")'
                );

                button.prop("disabled", true);

                try {

                    frappe.dom.freeze("Preparing Payroll Preview...");

                    let response = await frappe.call({
                        method: "tareqix_hrms.utils.payroll_export.get_payroll_preview",
                        args: {
                            payroll_entry_names: payroll_entry_names
                        }
                    });

                    let result = response.message;

                    if (!result || !result.rows || !result.rows.length) {

                        frappe.msgprint(
                            "No submitted payroll records found."
                        );

                        return;
                    }

                    show_payroll_preview(
                        result,
                        payroll_entry_names
                    );

                } catch (error) {

                    console.error("Payroll Preview Error:", error);

                    frappe.msgprint({
                        title: "Export Error",
                        message: error.message || "Unable to prepare payroll preview.",
                        indicator: "red"
                    });

                } finally {

                    frappe.dom.unfreeze();
                    button.prop("disabled", false);
                }
            }
        );
    }
};


function show_payroll_preview(data, payroll_entry_names) {

    let columns = data.columns || [];
    let rows = data.rows || [];

    function escape_html(value) {

        return String(value ?? "")
            .replace(/&/g, "&amp;")
            .replace(/</g, "&lt;")
            .replace(/>/g, "&gt;")
            .replace(/"/g, "&quot;")
            .replace(/'/g, "&#039;");
    }

    let table_html = `
        <div style="
            margin-bottom: 15px;
            display: flex;
            justify-content: space-between;
            align-items: center;
        ">
            <div>
                <b>Total Employees:</b> ${rows.length}
                <br>
                <span class="text-muted">
                    Only submitted Payroll Entry and Salary Slip records
                </span>
            </div>
        </div>

        <div style="
            overflow: auto;
            max-height: 65vh;
            border: 1px solid var(--border-color);
            border-radius: 6px;
        ">
            <table class="table table-bordered table-hover"
                   style="margin-bottom: 0; white-space: nowrap;">

                <thead>
                    <tr style="
                        position: sticky;
                        top: 0;
                        background: var(--control-bg);
                        z-index: 2;
                    ">
                        ${columns.map(column => `
                            <th>${escape_html(column)}</th>
                        `).join("")}
                    </tr>
                </thead>

                <tbody>
                    ${rows.map(row => `
                        <tr>
                            ${row.map(value => `
                                <td>${escape_html(value)}</td>
                            `).join("")}
                        </tr>
                    `).join("")}
                </tbody>

            </table>
        </div>
    `;

    let dialog = new frappe.ui.Dialog({

        title: "Payroll Excel Preview",

        size: "extra-large",

        fields: [
            {
                fieldtype: "HTML",
                fieldname: "payroll_preview"
            }
        ],

        primary_action_label: "Download Excel",

        primary_action: async function () {

            let download_button = dialog.get_primary_btn();

            download_button.prop("disabled", true);

            try {

                frappe.dom.freeze("Generating Excel File...");

                let response = await frappe.call({
                    method: "tareqix_hrms.utils.payroll_export.download_payroll_excel",
                    args: {
                        payroll_entry_names: payroll_entry_names
                    }
                });

                let result = response.message;

                if (!result || !result.file_data) {

                    frappe.throw("Excel file could not be generated.");
                }

                // Convert Base64 into Excel Blob
                let binary = atob(result.file_data);

                let bytes = new Uint8Array(binary.length);

                for (let i = 0; i < binary.length; i++) {
                    bytes[i] = binary.charCodeAt(i);
                }

                let blob = new Blob(
                    [bytes],
                    {
                        type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
                    }
                );

                let url = URL.createObjectURL(blob);

                let link = document.createElement("a");

                link.href = url;
                link.download = result.file_name || "Payroll_Export.xlsx";

                document.body.appendChild(link);
                link.click();
                document.body.removeChild(link);

                URL.revokeObjectURL(url);

                frappe.show_alert({
                    message: "Payroll Excel downloaded successfully.",
                    indicator: "green"
                });

            } catch (error) {

                console.error("Payroll Download Error:", error);

                frappe.msgprint({
                    title: "Download Error",
                    message: error.message || "Unable to download Excel file.",
                    indicator: "red"
                });

            } finally {

                frappe.dom.unfreeze();
                download_button.prop("disabled", false);
            }
        }
    });

    dialog.fields_dict.payroll_preview.$wrapper.html(table_html);

    // Cancel closes the preview dialog and returns to the List View.
dialog.set_secondary_action(function () {
    dialog.hide();
});

dialog.get_secondary_btn().text("Cancel");

    dialog.show();
}
